type R = Record<string, any>;
type Props = { csrfToken: string; readOnly: boolean; mode: 'fixture'|'live'; onContextChange?: (value:{workspace:ModelWorkspace;data_mode:'synthetic'|'imported'|'aps';project_name?:string})=>void; onBeforeLeaveChange?: (guard: (()=>Promise<boolean>)|null)=>void };
type Tab = 'sources'|'data'|'profiles'|'spaces'|'exports';
const draftMemory = new Map<string, unknown>();
const dirtyDrafts = new Set<string>();
export const hasModelDataDrafts = () => dirtyDrafts.size > 0;
function useDraft<T>(key: string, initial: T): [T, Dispatch<SetStateAction<T>>, (next?:T)=>void, boolean] {
  const [value, setValue] = useState<T>(()=>(draftMemory.get(key) as T|undefined)??initial);
  const [dirty, setDirty] = useState(dirtyDrafts.has(key));
  const initialRef = useRef(initial);
  useEffect(()=>{ initialRef.current=initial; setValue((draftMemory.get(key) as T|undefined)??initial);setDirty(dirtyDrafts.has(key)); },[key]);
  const change:Dispatch<SetStateAction<T>> = next => setValue(previous=>{const result=typeof next==='function'?(next as (p:T)=>T)(previous):next;draftMemory.set(key,result);dirtyDrafts.add(key);setDirty(true);return result;});
  const accept=(next?:T)=>{const result=next===undefined?initialRef.current:next;draftMemory.delete(key);dirtyDrafts.delete(key);setValue(result);setDirty(false);};
  return [value,change,accept,dirty];
}
function Field({ label, children, hint }: {label:string;children:ReactNode;hint?:string}) { return <label className="wb-field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>; }
function Panel({ title, description, children, action }: {title:string;description?:string;children:ReactNode;action?:ReactNode}) { return <section className="wb-panel"><div className="wb-panel-head"><div><h2>{title}</h2>{description&&<p>{description}</p>}</div>{action}</div><div className="wb-panel-body">{children}</div></section>; }
function Metadata({ rows }: { rows:[string,ReactNode][] }) { return <dl className="mdm-metadata">{rows.map(([key,value])=><div key={key}><dt>{key}</dt><dd>{value}</dd></div>)}</dl>; }
const stamp=(v:string)=>v?new Date(v).toLocaleString(): 'Not recorded';
const title=(v:unknown)=>String(v??'Unknown').replaceAll('_',' ');
const displayNumber=new Intl.NumberFormat(undefined,{maximumSignificantDigits:12});
const valueText=(value:unknown,unit?:string|null)=>value===null||value===undefined?'Unknown':`${typeof value==='number'?displayNumber.format(value):typeof value==='object'?JSON.stringify(value):String(value)}${unit?' '+unit:''}`;
const json=(value:unknown)=>JSON.stringify(value,null,2);
const tabs:{id:Tab;label:string}[]=[{id:'sources',label:'Sources & imports'},{id:'data',label:'Element data & review'},{id:'profiles',label:'Profiles & rules'},{id:'spaces',label:'Rooms & spaces'},{id:'exports',label:'Runs & fixed exports'}];
const blankProfile=():ProfileInput=>({name:'Equipment data profile',category:'Air Handling Units',fields:[{key:'manufacturer',label:'Manufacturer',source_names:['Manufacturer'],type:'text',required:true},{key:'airflow',label:'Design airflow',source_names:['Airflow','Supply Airflow'],type:'number',unit:'L/s',required:true}],classification_rules:[],metrics:[],spatial:{enabled:true,adjacency_tolerance_m:.15,containment_tolerance_m:.001}});
const profileInput=(profile:Profile):ProfileInput=>({profile_id:profile.profile_id,previous_revision_id:profile.revision_id,name:profile.name,category:profile.category,fields:profile.fields,classification_rules:profile.classification_rules,metrics:profile.metrics,spatial:profile.spatial});
function profileDraftFromJson(value:string):ProfileInput {
  const p=JSON.parse(value),object=(v:unknown):v is R=>!!v&&typeof v==='object'&&!Array.isArray(v),strings=(row:R,keys:string[])=>keys.every(key=>typeof row[key]==='string');
  if(!object(p)||!strings(p,['name','category'])||!Array.isArray(p.fields)||!Array.isArray(p.classification_rules)||!Array.isArray(p.metrics)||!object(p.spatial))throw Error('The profile needs name, category, fields, classification_rules, metrics and spatial settings.');
  if(!p.fields.every((f:unknown)=>object(f)&&strings(f,['key','label'])&&Array.isArray(f.source_names)&&f.source_names.every((v:unknown)=>typeof v==='string')&&['text','number','boolean'].includes(f.type)&&typeof f.required==='boolean'))throw Error('Each field needs a key, label, source_names string array, text/number/boolean type and required Boolean.');
  if(!p.classification_rules.every((r:unknown)=>object(r)&&strings(r,['rule_id','system_id','system_version','code','label'])&&['exists','equals','contains'].includes(r.operator)))throw Error('Each classification rule needs its identity, system/version, code, label and supported operator.');
  if(!p.metrics.every((m:unknown)=>object(m)&&strings(m,['metric_id','system_id','code','label','unit','basis'])&&['count','property','formula'].includes(m.method)&&(!m.aggregation||['sum','none'].includes(m.aggregation))))throw Error('Each metric needs its identity, classification, label, unit, basis and count/property/formula method.');
  if(typeof p.spatial.enabled!=='boolean'||!['adjacency_tolerance_m','containment_tolerance_m'].every(k=>typeof p.spatial[k]==='number'&&Number.isFinite(p.spatial[k])&&p.spatial[k]>=0))throw Error('Spatial settings need an enabled Boolean and finite non-negative tolerances in metres.');
  return p as ProfileInput;
}

