  const [dataset,setDataset]=useState<Dataset|null>(null),[run,setRun]=useState<ModelRun|null>(null),[selected,setSelected]=useState('');
  const [error,setError]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[refresh,setRefresh]=useState(0),[query,setQuery]=useState(''),[category,setCategory]=useState(''),[classification,setClassification]=useState(''),[quality,setQuality]=useState('all');
  const [catalogQuery,setCatalogQuery]=useState(''),[designation,setDesignation]=useState(''),[libraryQuery,setLibraryQuery]=useState(''),[libraryRows,setLibraryRows]=useState<R[]>([]),[libraryBusy,setLibraryBusy]=useState(false),[librarySearched,setLibrarySearched]=useState(false);
  const [profileEditor,setProfileEditor]=useState(''),[leavePrompt,setLeavePrompt]=useState(false);
  const pendingLeave=useRef<((answer:boolean)=>void)|null>(null),busyRef=useRef(false),contextRef=useRef(''),leaveDialog=useRef<HTMLElement|null>(null),libraryRequest=useRef<AbortController|null>(null);
