  useEffect(()=>{const controller=new AbortController();setData(null);setError('');fetch(base+'/bootstrap',{credentials:'same-origin',signal:controller.signal}).then(async response=>{const body=await response.json();if(!response.ok)throw Error(body.error||'Model-data workspace unavailable.');setData(body);setDatasetId(current=>body.datasets.some((d:R)=>d.dataset_id===current)?current:body.datasets[0]?.dataset_id??'');setProfileId(current=>body.profiles.some((p:R)=>p.profile_id===current)?current:body.profiles[0]?.profile_id??'');setProfileEditor(current=>current==='new'||body.profiles.some((p:R)=>p.profile_id===current)?current:body.profiles[0]?.profile_id??'new');}).catch(cause=>{if(!controller.signal.aborted)setError(cause.message);});return()=>controller.abort();},[base,refresh]);
  useEffect(()=>{setDataset(null);setRun(null);setSelected('');setRunId('');setLibraryRows([]);setLibrarySearched(false);libraryRequest.current?.abort();return()=>libraryRequest.current?.abort();},[base]);
  useEffect(()=>{setQuery('');setCategory('');setClassification('');setQuality('all');},[datasetId]);
