  function openSourceResults(id:string){const latest=data?.runs.filter(r=>r.dataset_id===id).at(-1);setDatasetId(id);setRunId(latest?.run_id??'');setSelected(current=>run&&run.run_id===latest?.run_id?(run.results.some(row=>row.element_key===current)?current:run.results[0]?.element_key??''):'');setQuery('');setCategory('');setClassification('');setQuality('all');setTab('data');}
